import os, json, glob
from collections import defaultdict, Counter

def load_json(p):
    with open(p, "r", encoding="utf-8") as f:
        return json.load(f)

def per_agent_persistence(actions, creation_set):
    by_agent_counts = defaultdict(Counter)
    for a in actions:
        aid = a.get("agent_id", "unknown")
        atype = a.get("action_type", "unknown")
        by_agent_counts[aid][atype] += 1
    rates = {}
    for aid, cnts in by_agent_counts.items():
        total = sum(cnts.values())
        creation = sum(cnts[t] for t in cnts if t in creation_set)
        rates[aid] = (creation / total) if total > 0 else 0.0
    return rates

def main():
    base = "storage/shared/agency_lab"
    out_dir = os.path.join(base, "analyses")
    os.makedirs(out_dir, exist_ok=True)
    out_txt = os.path.join(out_dir, "cross_persistence_v1_2.txt")
    out_json = os.path.join(out_dir, "cross_persistence_v1_2.json")

    paths = glob.glob(os.path.join(base, "*_actions_v1_2*.json"))
    creation_set = {"create", "build", "generate", "initialize"}

    results = []
    for p in sorted(paths):
        try:
            batch = load_json(p)
            lineage = batch.get("lineage", "unknown")
            actions = batch.get("actions", [])
            rates = per_agent_persistence(actions, creation_set)
            if rates:
                mean_rate = sum(rates.values()) / len(rates)
            else:
                mean_rate = None
            results.append({"file": os.path.basename(p), "lineage": lineage, "agents": len(rates), "mean_persistence_rate": mean_rate})
        except Exception as e:
            results.append({"file": os.path.basename(p), "error": str(e)})

    # Write JSON
    with open(out_json, "w", encoding="utf-8") as f:
        json.dump({"results": results}, f, ensure_ascii=False, indent=2)

    # Write text
    lines = ["file\tlineage\tagents\tmean_persistence_rate"]
    for r in results:
        if "error" in r:
            lines.append(f"{r['file']}\tERROR\t0\tNA")
        else:
            m = "NA" if r["mean_persistence_rate"] is None else f"{r['mean_persistence_rate']:.6f}"
            lines.append(f"{r['file']}\t{r['lineage']}\t{r['agents']}\t{m}")
    with open(out_txt, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))

    print("WROTE", out_txt)
    print("WROTE", out_json)
    for line in lines[:5]:
        print(line)
    return 0

if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as e:
        print("ERROR", str(e))
        raise SystemExit(1)
